//! SSH tunnel integration tests (M3-1 / US-02).
//!
//! Skipped unless `SELA_SSH_HOST` (and related vars) are set — same pattern as
//! `SELA_POSTGRES_URL` / `postgres_tls`. Keys and known_hosts are generated by
//! `scripts/run-ssh-bastion.sh` at runtime; never committed.
//!
//! Test names include the QA plan ids from `docs/qa/v0.3-test-plan.md`.

use std::path::PathBuf;
use std::time::Duration;

use sela_core::{
    DbError, Engine, SavedConnection, SshAuthMethod, SshSettings, TlsMode, TlsSettings,
};
use sela_drivers::{connect_with_auth, ConnectAuth, ConnectOutcome, SshAuthSecrets, SshPaths};
use sela_ssh::{open_tunnel, TunnelOpen, TunnelRequest};

struct SshEnv {
    host: String,
    port: u16,
    user: String,
    password: String,
    key: PathBuf,
    key_encrypted: PathBuf,
    key_passphrase: String,
    known_hosts: PathBuf,
    known_hosts_bad: PathBuf,
    db_host: String,
    db_port: u16,
    db_user: String,
    db_password: String,
    db_name: String,
    mysql_host: Option<String>,
    mysql_port: Option<u16>,
    home: PathBuf,
}

fn ssh_env() -> Option<SshEnv> {
    let host = std::env::var("SELA_SSH_HOST").ok()?;
    let port: u16 = std::env::var("SELA_SSH_PORT").ok()?.parse().ok()?;
    let user = std::env::var("SELA_SSH_USER").ok()?;
    let password = std::env::var("SELA_SSH_PASSWORD").ok()?;
    let key = PathBuf::from(std::env::var("SELA_SSH_KEY").ok()?);
    let key_encrypted = PathBuf::from(std::env::var("SELA_SSH_KEY_ENCRYPTED").ok()?);
    let key_passphrase = std::env::var("SELA_SSH_KEY_PASSPHRASE").ok()?;
    let known_hosts = PathBuf::from(std::env::var("SELA_SSH_KNOWN_HOSTS").ok()?);
    let known_hosts_bad = PathBuf::from(std::env::var("SELA_SSH_KNOWN_HOSTS_BAD").ok()?);
    let db_host = std::env::var("SELA_SSH_DB_HOST").ok()?;
    let db_port: u16 = std::env::var("SELA_SSH_DB_PORT")
        .ok()
        .and_then(|p| p.parse().ok())
        .unwrap_or(5432);
    let db_user = std::env::var("SELA_SSH_DB_USER").unwrap_or_else(|_| "sela".into());
    let db_password = std::env::var("SELA_SSH_DB_PASSWORD").unwrap_or_else(|_| "sela".into());
    let db_name = std::env::var("SELA_SSH_DB_NAME").unwrap_or_else(|_| "sample".into());
    let mysql_host = std::env::var("SELA_SSH_MYSQL_HOST").ok();
    let mysql_port = std::env::var("SELA_SSH_MYSQL_PORT")
        .ok()
        .and_then(|p| p.parse().ok());
    let home = known_hosts
        .parent()
        .and_then(|p| p.parent())
        .map(|p| p.to_path_buf())
        .unwrap_or_else(|| PathBuf::from("."));
    Some(SshEnv {
        host,
        port,
        user,
        password,
        key,
        key_encrypted,
        key_passphrase,
        known_hosts,
        known_hosts_bad,
        db_host,
        db_port,
        db_user,
        db_password,
        db_name,
        mysql_host,
        mysql_port,
        home,
    })
}

fn paths(env: &SshEnv) -> SshPaths {
    SshPaths::from_home(&env.home)
        .with_known_hosts(env.known_hosts.clone())
        .without_config()
}

fn pg_connection(env: &SshEnv, ssh: SshSettings) -> SavedConnection {
    let mut c = SavedConnection::new(Engine::Postgres);
    c.name = "ssh-ci".into();
    c.host = env.db_host.clone();
    c.port = env.db_port;
    c.username = env.db_user.clone();
    c.database = env.db_name.clone();
    c.tls = TlsSettings {
        mode: TlsMode::Disable,
        ..TlsSettings::default()
    };
    c.ssh = ssh;
    c
}

fn password_ssh(env: &SshEnv) -> SshSettings {
    SshSettings {
        enabled: true,
        host: env.host.clone(),
        port: env.port,
        user: env.user.clone(),
        auth: SshAuthMethod::Password,
        identity_file: String::new(),
        use_ssh_config: false,
    }
}

fn key_ssh(env: &SshEnv, encrypted: bool) -> SshSettings {
    SshSettings {
        enabled: true,
        host: env.host.clone(),
        port: env.port,
        user: env.user.clone(),
        auth: SshAuthMethod::PrivateKey,
        identity_file: if encrypted {
            env.key_encrypted.display().to_string()
        } else {
            env.key.display().to_string()
        },
        use_ssh_config: false,
    }
}

fn auth_password(env: &SshEnv) -> ConnectAuth {
    ConnectAuth {
        db_password: env.db_password.clone(),
        ssh: SshAuthSecrets {
            password: Some(env.password.clone()),
            passphrase: None,
        },
        ssh_paths: Some(paths(env)),
    }
}

fn auth_key(env: &SshEnv, passphrase: Option<String>) -> ConnectAuth {
    ConnectAuth {
        db_password: env.db_password.clone(),
        ssh: SshAuthSecrets {
            password: None,
            passphrase,
        },
        ssh_paths: Some(paths(env)),
    }
}

async fn assert_select_one(session: &dyn sela_core::DatabaseSession) {
    let page = session.query("SELECT 1 AS n").await.expect("SELECT 1");
    assert!(!page.rows.is_empty(), "expected a row through the tunnel");
}

#[tokio::test]
async fn ssh01_password_auth_then_postgres_query() {
    let Some(env) = ssh_env() else {
        eprintln!("skip SSH: set SELA_SSH_HOST (and related) to run");
        return;
    };
    let conn = pg_connection(&env, password_ssh(&env));
    let outcome = connect_with_auth(&conn, auth_password(&env))
        .await
        .expect("SSH password connect");
    let ConnectOutcome::Ready(session) = outcome else {
        panic!("expected Ready with known_hosts present");
    };
    assert_select_one(session.as_ref()).await;
}

