#[tokio::test]
async fn ssh03_private_key_with_passphrase() {
    let Some(env) = ssh_env() else {
        eprintln!("skip SSH: set SELA_SSH_HOST (and related) to run");
        return;
    };
    let conn = pg_connection(&env, key_ssh(&env, true));
    // Wrong passphrase → SSH auth, not DB auth.
    let bad = connect_with_auth(&conn, auth_key(&env, Some("wrong-passphrase".into()))).await;
    match bad {
        Err(err) => assert!(
            matches!(err, DbError::Ssh { .. }),
            "wrong passphrase must be DbError::Ssh, got {err:?}"
        ),
        Ok(_) => panic!("wrong passphrase must fail"),
    }

    let outcome = connect_with_auth(&conn, auth_key(&env, Some(env.key_passphrase.clone())))
        .await
        .expect("SSH encrypted key connect");
    let ConnectOutcome::Ready(session) = outcome else {
        panic!("expected Ready");
    };
    assert_select_one(session.as_ref()).await;
}

