#[tokio::test]
async fn ssh05_ssh_config_host_alias() {
    let Some(env) = ssh_env() else {
        eprintln!("skip SSH: set SELA_SSH_HOST (and related) to run");
        return;
    };
    // Write a temp config under the injectable home (already used for known_hosts).
    let ssh_dir = env.home.join(".ssh");
    std::fs::create_dir_all(&ssh_dir).ok();
    let config_path = ssh_dir.join("config");
    std::fs::write(
        &config_path,
        format!(
            "Host jump\n  HostName {}\n  User {}\n  Port {}\n  IdentityFile {}\n",
            env.host,
            env.user,
            env.port,
            env.key.display()
        ),
    )
    .unwrap();
    let mut paths = SshPaths::from_home(&env.home).with_known_hosts(env.known_hosts.clone());
    paths.config = Some(config_path);

    let ssh = SshSettings {
        enabled: true,
        host: "jump".into(),
        auth: SshAuthMethod::PrivateKey,
        use_ssh_config: true,
        ..SshSettings::default()
    };
    // Port/user/identity left empty → filled from config.
    let conn = pg_connection(&env, ssh);
    let outcome = connect_with_auth(
        &conn,
        ConnectAuth {
            db_password: env.db_password.clone(),
            ssh: SshAuthSecrets::default(),
            ssh_paths: Some(paths),
        },
    )
    .await
    .expect("SSH config alias connect");
    let ConnectOutcome::Ready(session) = outcome else {
        panic!("expected Ready");
    };
    assert_select_one(session.as_ref()).await;
}

#[tokio::test]
async fn ssh06_matching_known_hosts_allows() {
    // Covered by ssh01–ssh05 when SELA_SSH_KNOWN_HOSTS is correct.
    let Some(env) = ssh_env() else {
        eprintln!("skip SSH: set SELA_SSH_HOST (and related) to run");
        return;
    };
    assert!(env.known_hosts.is_file());
    let conn = pg_connection(&env, password_ssh(&env));
    let outcome = connect_with_auth(&conn, auth_password(&env))
        .await
        .expect("known_hosts match");
    assert!(matches!(outcome, ConnectOutcome::Ready(_)));
}

#[tokio::test]
async fn ssh07_wrong_host_key_rejected() {
    let Some(env) = ssh_env() else {
        eprintln!("skip SSH: set SELA_SSH_HOST (and related) to run");
        return;
    };
    let mut paths = paths(&env);
    paths.known_hosts = env.known_hosts_bad.clone();
    let conn = pg_connection(&env, password_ssh(&env));
    let err = connect_with_auth(
        &conn,
        ConnectAuth {
            db_password: env.db_password.clone(),
            ssh: SshAuthSecrets {
                password: Some(env.password.clone()),
                passphrase: None,
            },
            ssh_paths: Some(paths),
        },
    )
    .await
    .expect_err("mismatch must fail before DB");
    assert!(
        matches!(err, DbError::Ssh { .. }),
        "host-key mismatch must be DbError::Ssh, got {err:?}"
    );
    let msg = err.to_string();
    assert!(
        msg.to_ascii_lowercase().contains("host key")
            || msg.to_ascii_lowercase().contains("known_hosts"),
        "message should mention host key: {msg}"
    );
}

#[tokio::test]
async fn ssh08_ssh_errors_distinct_from_db_auth() {
    let Some(env) = ssh_env() else {
        eprintln!("skip SSH: set SELA_SSH_HOST (and related) to run");
        return;
    };
    // Bad SSH password → Ssh, not Auth.
    let conn = pg_connection(&env, password_ssh(&env));
    let mut bad_ssh = auth_password(&env);
    bad_ssh.ssh.password = Some("not-the-bastion-password".into());
    let err = connect_with_auth(&conn, bad_ssh)
        .await
        .expect_err("bad SSH password");
    assert!(matches!(err, DbError::Ssh { .. }), "got {err:?}");

    // Good tunnel + bad DB password → Auth (or Connection), not Ssh.
    let mut bad_db = auth_password(&env);
    bad_db.db_password = "wrong-db-password".into();
    let err = connect_with_auth(&conn, bad_db)
        .await
        .expect_err("bad DB password");
    assert!(
        matches!(err, DbError::Auth { .. } | DbError::Connection { .. }),
        "good tunnel + bad DB password must not be Ssh, got {err:?}"
    );
    assert!(!matches!(err, DbError::Ssh { .. }));
}

#[tokio::test]
async fn ssh09_driver_dials_loopback_ephemeral() {
    let Some(env) = ssh_env() else {
        eprintln!("skip SSH: set SELA_SSH_HOST (and related) to run");
        return;
    };
    let request = TunnelRequest {
        ssh: password_ssh(&env),
        remote_db_host: env.db_host.clone(),
        remote_db_port: env.db_port,
        secrets: SshAuthSecrets {
            password: Some(env.password.clone()),
            passphrase: None,
        },
        paths: paths(&env),
    };
    let TunnelOpen::Ready(tunnel) = open_tunnel(request).await.expect("open tunnel") else {
        panic!("expected Ready");
    };
    let addr = tunnel.local_addr();
    assert!(addr.ip().is_loopback());
    assert_ne!(addr.port(), 0);
    assert_ne!(addr.port(), env.db_port, "must not expose the real DB port");
    tunnel.close().await;
}

#[tokio::test]
async fn ssh10_close_releases_local_port() {
    let Some(env) = ssh_env() else {
        eprintln!("skip SSH: set SELA_SSH_HOST (and related) to run");
        return;
    };
    let conn = pg_connection(&env, password_ssh(&env));
    let outcome = connect_with_auth(&conn, auth_password(&env))
        .await
        .expect("connect");
    let ConnectOutcome::Ready(session) = outcome else {
        panic!("expected Ready");
    };
    // Capture nothing from session; close drops the tunnel.
    session.close().await;
    // A second connect must succeed (port free again).
    let outcome2 = connect_with_auth(&conn, auth_password(&env))
        .await
        .expect("reconnect after close");
    assert!(matches!(outcome2, ConnectOutcome::Ready(_)));
}

#[tokio::test]
async fn ssh12_ephemeral_bind_does_not_use_foreign_port() {
    // Binding 127.0.0.1:0 never collides with a fixed foreign port; assert the
    // listener is loopback ephemeral (same as SSH-09). Collision retry is the
    // OS bind of port 0 — if bind fails we surface SshError::Io.
    let Some(env) = ssh_env() else {
        eprintln!("skip SSH: set SELA_SSH_HOST (and related) to run");
        return;
    };
    let request = TunnelRequest {
        ssh: password_ssh(&env),
        remote_db_host: env.db_host.clone(),
        remote_db_port: env.db_port,
        secrets: SshAuthSecrets {
            password: Some(env.password.clone()),
            passphrase: None,
        },
        paths: paths(&env),
    };
    let TunnelOpen::Ready(tunnel) = open_tunnel(request).await.expect("open tunnel") else {
        panic!("expected Ready");
    };
    assert!(tunnel.local_addr().ip().is_loopback());
    assert_ne!(tunnel.local_port(), env.db_port);
    tunnel.close().await;
}

