#[tokio::test]
async fn ssh17_mysql_through_tunnel() {
    let Some(env) = ssh_env() else {
        eprintln!("skip SSH: set SELA_SSH_HOST (and related) to run");
        return;
    };
    let Some(mysql_host) = env.mysql_host.clone() else {
        eprintln!("skip SSH-17: set SELA_SSH_MYSQL_HOST to exercise MySQL through the bastion");
        return;
    };
    let mysql_port = env.mysql_port.unwrap_or(3306);
    let mut c = SavedConnection::new(Engine::Mysql);
    c.name = "ssh-mysql".into();
    c.host = mysql_host;
    c.port = mysql_port;
    c.username = env.db_user.clone();
    c.database = env.db_name.clone();
    c.tls.mode = TlsMode::Disable;
    c.ssh = password_ssh(&env);

    // SSH auth failure.
    let mut bad = auth_password(&env);
    bad.ssh.password = Some("nope".into());
    let err = connect_with_auth(&c, bad).await.expect_err("bad SSH");
    assert!(matches!(err, DbError::Ssh { .. }));

    let outcome = connect_with_auth(&c, auth_password(&env))
        .await
        .expect("MySQL via SSH");
    let ConnectOutcome::Ready(session) = outcome else {
        panic!("expected Ready");
    };
    assert_select_one(session.as_ref()).await;
}

#[tokio::test]
async fn ssh18_unknown_host_key_challenge_then_accept() {
    let Some(env) = ssh_env() else {
        eprintln!("skip SSH: set SELA_SSH_HOST (and related) to run");
        return;
    };
    let empty_known = env.home.join(".ssh").join("known_hosts.empty");
    let _ = std::fs::remove_file(&empty_known);
    std::fs::File::create(&empty_known).unwrap();
    let mut paths = paths(&env);
    paths.known_hosts = empty_known.clone();

    let conn = pg_connection(&env, password_ssh(&env));
    let outcome = connect_with_auth(
        &conn,
        ConnectAuth {
            db_password: env.db_password.clone(),
            ssh: SshAuthSecrets {
                password: Some(env.password.clone()),
                passphrase: None,
            },
            ssh_paths: Some(paths),
        },
    )
    .await
    .expect("unknown host returns outcome");
    let ConnectOutcome::UnknownSshHostKey(challenge) = outcome else {
        panic!("expected UnknownSshHostKey challenge");
    };
    assert!(
        challenge.fingerprint.starts_with("SHA256:"),
        "fingerprint={}",
        challenge.fingerprint
    );
    // Reject path (typed error).
    let rejected = challenge.reject();
    assert!(matches!(rejected, DbError::Ssh { .. }));

    // Fresh challenge → accept_and_remember.
    let paths = SshPaths::from_home(&env.home)
        .with_known_hosts(empty_known.clone())
        .without_config();
    let outcome = connect_with_auth(
        &conn,
        ConnectAuth {
            db_password: env.db_password.clone(),
            ssh: SshAuthSecrets {
                password: Some(env.password.clone()),
                passphrase: None,
            },
            ssh_paths: Some(paths),
        },
    )
    .await
    .expect("second unknown");
    let ConnectOutcome::UnknownSshHostKey(challenge) = outcome else {
        panic!("expected challenge again");
    };
    let session = (*challenge)
        .accept_and_remember()
        .await
        .expect("accept_and_remember");
    assert_select_one(session.as_ref()).await;
    let written = std::fs::read_to_string(&empty_known).unwrap();
    assert!(
        written.contains(&env.host) || written.contains(&format!("[{}]:{}", env.host, env.port)),
        "known_hosts should record the host after accept"
    );

    // Changed key remains a hard error (no override) — covered by ssh07.
    let _ = Duration::from_secs(0);
}

#[tokio::test]
async fn ssh11_tunnel_drop_mid_query_surfaces_error() {
    let Some(env) = ssh_env() else {
        eprintln!("skip SSH: set SELA_SSH_HOST (and related) to run");
        return;
    };
    let conn = pg_connection(&env, password_ssh(&env));
    let outcome = connect_with_auth(&conn, auth_password(&env))
        .await
        .expect("connect");
    let ConnectOutcome::Ready(session) = outcome else {
        panic!("expected Ready");
    };
    // Drop the session (closes tunnel) while… we can't easily race pg_sleep
    // without holding the tunnel handle separately. Open a tunnel, start a
    // raw TCP query path via connect, then close the tunnel under the session
    // by dropping — session.close cancels the pool; a subsequent query fails
    // without panic.
    session.close().await;
    let err = session.query("SELECT 1").await.expect_err("after close");
    assert!(
        matches!(
            err,
            DbError::Connection { .. } | DbError::Internal { .. } | DbError::Query { .. }
        ),
        "got {err:?}"
    );
    // Reconnect still works (SSH-11).
    let again = connect_with_auth(&conn, auth_password(&env))
        .await
        .expect("reconnect after drop");
    assert!(matches!(again, ConnectOutcome::Ready(_)));
}
